CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 TEXT COLLATE NOCASE, c1 TEXT COLLATE NOCASE, c2 ANY, c3 REAL NOT NULL DEFAULT 0, c4 ANY) STRICT;
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES('iota', 'theta', 'theta', -34.724, -2);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES('x_y', 'tau', -76, -16.865, -544);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES('-7', 'MU', x'363dffa000', 23.087, NULL);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES('alpha', 'nu', 3, 46.296, -4);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES('theta', 'epsilon', x'', 44.942, NULL);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES('gamma', 'iota', -33, -37.342, NULL);
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 VARCHAR(10) DEFAULT 'd', c1 INTEGER NOT NULL DEFAULT 0, c2 VARCHAR(10) DEFAULT 'd');
SELECT length('eta'), upper('eta'), lower('eta'), substr('eta', 4, 2), instr('eta', 'eta'), replace('eta', 'a', ''), trim('eta'), ltrim('eta', 'ab'), hex('eta'), quote('eta'), unicode('eta'), 'eta' LIKE 'a%', 'eta' GLOB 'a*', char(87, 725), 'eta' || 'eta', 'eta' < 'eta', 'eta' = 'eta' COLLATE NOCASE;
SELECT length(''), upper(''), lower(''), substr('', 1, 0), instr('', '42'), replace('', 'e', 'XY'), trim(''), ltrim('', 'ab'), hex(''), quote(''), unicode(''), '' LIKE '_', '' GLOB '?', char(80, 483), '' || '42', '' < '42', '' = '42' COLLATE NOCASE;
SELECT length('delta'), upper('delta'), lower('delta'), substr('delta', 1, 2), instr('delta', 'beta'), replace('delta', 'a', ''), trim('delta'), ltrim('delta', 'ab'), hex('delta'), quote('delta'), unicode('delta'), 'delta' LIKE '_', 'delta' GLOB 'a*', char(77, 505), 'delta' || 'beta', 'delta' < 'beta', 'delta' = 'beta' COLLATE NOCASE;
SELECT length('nu'), upper('nu'), lower('nu'), substr('nu', 2, 0), instr('nu', 'iota'), replace('nu', 'é', ''), trim('nu'), ltrim('nu', 'ab'), hex('nu'), quote('nu'), unicode('nu'), 'nu' LIKE 'A%', 'nu' GLOB '*', char(70, 455), 'nu' || 'iota', 'nu' < 'iota', 'nu' = 'iota' COLLATE NOCASE;
SELECT length('naïve'), upper('naïve'), lower('naïve'), substr('naïve', 3, 4), instr('naïve', 'naïve'), replace('naïve', '', 'XY'), trim('naïve'), ltrim('naïve', 'ab'), hex('naïve'), quote('naïve'), unicode('naïve'), 'naïve' LIKE 'a%', 'naïve' GLOB 'a*', char(87, 627), 'naïve' || 'naïve', 'naïve' < 'naïve', 'naïve' = 'naïve' COLLATE NOCASE;
SELECT length('beta'), upper('beta'), lower('beta'), substr('beta', 3, 5), instr('beta', 'psi'), replace('beta', 'e', 'XY'), trim('beta'), ltrim('beta', 'ab'), hex('beta'), quote('beta'), unicode('beta'), 'beta' LIKE '%a_', 'beta' GLOB '*[a-m]*', char(74, 675), 'beta' || 'psi', 'beta' < 'psi', 'beta' = 'psi' COLLATE NOCASE;
SELECT a.id, b.id, a.c4, b.c2 FROM t0 a LEFT JOIN t1 b ON a.id = b.id ORDER BY 1, 2 LIMIT 18;
SELECT count(*) FROM t0 a JOIN t0 b USING(id);
SELECT id, (SELECT count(*) FROM t1 WHERE t1.id <= t0.id) FROM t0 ORDER BY id DESC, id;
SELECT id FROM t0 WHERE id IN (SELECT id FROM t1 WHERE nullif(coalesce(-556, c1), 5)) ORDER BY id;
SELECT id FROM t0 x WHERE EXISTS (SELECT 1 FROM t1 y WHERE y.id = x.id + 0) ORDER BY id;
SELECT c1 FROM t0 EXCEPT SELECT c1 FROM t1 ORDER BY 1 LIMIT 15 OFFSET 2;
